import subprocess
def run(args, src):
    p=subprocess.run(args+["-c",src],capture_output=True,text=True)
    return p.returncode, (p.stdout.strip()[:50], p.stderr.strip().splitlines()[-1][:80] if p.stderr.strip() else "")
